CREATE TABLE IF NOT EXISTS `app_settings` (`value` TEXT, `id` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `deleted` INTEGER NOT NULL, `syncState` INTEGER NOT NULL, PRIMARY KEY(`id`));
